package com.enterprise.procurement.persistence.entity;
import com.baomidou.mybatisplus.annotation.*;
@TableName("sys_supplier") public class SupplierEntity { @TableId private Long id; private String code; private String name; private String contact; private String phone; private String address; private Integer active=1; public Long getId(){return id;} public void setId(Long v){id=v;} public String getCode(){return code;} public void setCode(String v){code=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getContact(){return contact;} public void setContact(String v){contact=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} public String getAddress(){return address;} public void setAddress(String v){address=v;} public Integer getActive(){return active;} public void setActive(Integer v){active=v;} }
